    @inline(__always)
    private func checkMultiplySubtractingAddingConstantAAlternating(_ even: Lane, _ odd: Lane) {
        let mismatches = Mismatches(
            "multiplySubtractingAdding with a alternating \(hex(even)), \(hex(odd))"
        )
        let bInputs = Inputs.vectors(H.self, seed: 0x5BE7_94BF_CE04_849D)
        let cInputs = Inputs.vectors(H.self, seed: 0x5BE7_91BF_CE04_7F84)
        mismatches.check(
            H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
            H(raw: HighwayReference.repeatingBlockI16(even, odd, even, odd, even, odd, even, odd)),
            "repeatingBlock"
        )
        for (b, c) in everyPair(bInputs, cInputs) {
            mismatches.check(
                H.multiplySubtractingAdding(
                    H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
                    b,
                    c
                ),
                H(
                    raw: HighwayReference.multiplySubtractingAddingI16(
                        H.repeatingBlock(even, odd, even, odd, even, odd, even, odd).raw,
                        b.raw,
                        c.raw
                    )
                ),
                "b: \(describe(b)), c: \(describe(c))"
            )
        }
        mismatches.record()
    }

